SELECT AVG(orders_per_user)
FROM (
  SELECT user_id, COUNT(order_id) AS orders_per_user
  FROM Orders
  GROUP BY user_id
) AS user_orders;

SELECT ROUND(100 * COUNT(DISTINCT user_id) / (SELECT COUNT(*) FROM Orders), 2)
FROM Orders
WHERE user_id IN (SELECT user_id FROM Orders GROUP BY user_id HAVING COUNT(*) >= 2);

SELECT COUNT(*)
FROM Orders
WHERE status IN ('shipped', 'completed') AND shipping_address IS NULL;

SELECT AVG(quantity)
FROM Order_Items
GROUP BY order_id;

SELECT
    (CAST(
        (SELECT COUNT(DISTINCT user_id)
         FROM Orders
         GROUP BY user_id
         HAVING COUNT(*) >= 2) AS REAL
    ) / CAST(
        (SELECT COUNT(DISTINCT user_id)
         FROM Orders) AS REAL
    )) * 100 AS percentage_of_users_with_two_or_more_orders;

SELECT AVG(total_qty) 
FROM (
    SELECT order_id, SUM(quantity) AS total_qty
    FROM Order_Items
    GROUP BY order_id
);
